package com.hospital.service.impl;
import com.hospital.entity.Appointment; import com.hospital.entity.Doctor; import com.hospital.entity.Patient; import com.hospital.repository.AppointmentRepository; import com.hospital.repository.DoctorRepository; import com.hospital.repository.PatientRepository; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.time.LocalDate; import java.time.LocalTime; import java.util.List; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AppointmentServiceImplTest {
 @Mock AppointmentRepository appointments; @Mock DoctorRepository doctors; @Mock PatientRepository patients; @InjectMocks AppointmentServiceImpl service;
 private Appointment sample(){Appointment a=new Appointment();a.setDoctorId(4);a.setPatientId(8);a.setAppointmentDate(LocalDate.of(2026,12,1));a.setAppointmentTime(LocalTime.of(10,0));a.setStatus("SCHEDULED");return a;}
 @Test void createsWhenReferencesExistAndSlotFree(){Appointment a=sample();when(doctors.lockById(4)).thenReturn(Optional.of(new Doctor()));when(patients.lockById(8)).thenReturn(Optional.of(new Patient()));when(appointments.findDoctorSlotConflicts(4,a.getAppointmentDate(),a.getAppointmentTime(),null)).thenReturn(List.of());when(appointments.findPatientSlotConflicts(8,a.getAppointmentDate(),a.getAppointmentTime(),null)).thenReturn(List.of());when(appointments.save(a)).thenReturn(a);assertEquals(a,service.create(a));verify(appointments).save(a);}
 @Test void rejectsDoctorConflict(){Appointment a=sample();when(doctors.lockById(4)).thenReturn(Optional.of(new Doctor()));when(patients.lockById(8)).thenReturn(Optional.of(new Patient()));when(appointments.findDoctorSlotConflicts(4,a.getAppointmentDate(),a.getAppointmentTime(),null)).thenReturn(List.of(new Appointment()));assertThrows(IllegalArgumentException.class,()->service.create(a));verify(appointments,never()).save(any());}
 @Test void rejectsPatientConflict(){Appointment a=sample();when(doctors.lockById(4)).thenReturn(Optional.of(new Doctor()));when(patients.lockById(8)).thenReturn(Optional.of(new Patient()));when(appointments.findDoctorSlotConflicts(4,a.getAppointmentDate(),a.getAppointmentTime(),null)).thenReturn(List.of());when(appointments.findPatientSlotConflicts(8,a.getAppointmentDate(),a.getAppointmentTime(),null)).thenReturn(List.of(new Appointment()));assertThrows(IllegalArgumentException.class,()->service.create(a));}
 @Test void canceledAppointmentDoesNotBlockSlot(){Appointment a=sample();a.setStatus("CANCELLED");when(doctors.lockById(4)).thenReturn(Optional.of(new Doctor()));when(patients.lockById(8)).thenReturn(Optional.of(new Patient()));when(appointments.save(a)).thenReturn(a);assertEquals(a,service.create(a));verify(appointments,never()).findDoctorSlotConflicts(any(),any(),any(),any());}
 @Test void rejectsMissingDoctor(){Appointment a=sample();when(doctors.lockById(4)).thenReturn(Optional.empty());assertThrows(RuntimeException.class,()->service.create(a));}
}
